def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n >= 99:
        return 'D'
    my_last, opp_last = history[-1]
    opp_c = sum(1 for a, b in history if b == 'C')
    opp_d = n - opp_c
    my_c = sum(1 for a, b in history if a == 'C')
    if n < 10:
        if opp_last == 'D' and my_last == 'C':
            return 'D'
        return 'C'
    opp_rate = opp_c / n
    recent = history[-10:]
    recent_opp_d = sum(1 for a, b in recent if b == 'D')
    recent_opp_c = 10 - recent_opp_d
    if recent_opp_d >= 8:
        return 'D'
    if recent_opp_c >= 9:
        return 'C'
    if opp_rate >= 0.8:
        return 'C'
    if opp_rate <= 0.3:
        return 'D'
    if my_last == 'C' and opp_last == 'D':
        return 'D'
    if my_last == 'D' and opp_last == 'C':
        return 'C'
    if n >= 20:
        last20 = history[-20:]
        d_after_d = sum(1 for i in range(1, len(last20)) if last20[i-1][1] == 'D' and last20[i][1] == 'D')
        if d_after_d >= 5:
            return 'D'
    if opp_rate > 0.5:
        return 'C'
    return 'C' if rng.random() < 0.5 else 'D'
